test('Practice transcriptions overlap within a bounded window and reconstruct seller evidence in packet order',async()=>{
 const playbookText='# Orchard Practice\n## Opening\nSet a clear purpose for this conversation.\n## Discovery\nAsk what outcome would help your team.',f=await setup({synthetic:true,practiceTurnMode:'turn_based_v1',audioDelay:body=>body.sequence===0?120:15,audioText:body=>body.sequence===0?'First part of the seller turn.':'Second part completes the seller turn.'});
 try{await act(()=>f.tree.root.findByType('select').props.onChange({target:{value:'scripted'}}));const file=f.tree.root.findAllByType('input').find(input=>input.props.type==='file');await act(async()=>file.props.onChange({currentTarget:{files:[{name:'orchard.md',size:playbookText.length,text:async()=>playbookText}]}}));await start(f);await f.activity();await f.chunk();await f.chunk();await waitFor(f,()=>f.calls.filter(call=>call.action==='audio').length===2);await waitFor(f,()=>f.calls.filter(call=>call.action==='audio').every(call=>call.completedAt!==undefined));const [first,second]=f.calls.filter(call=>call.action==='audio');assert.ok(second.startedAt<first.completedAt,`the later request starts before the slower first transcription completes: ${JSON.stringify({first,second})}`);assert.ok(second.completedAt<first.completedAt,'results can complete out of order');await waitFor(f,()=>diagnostics(f).transcriptTranscribed===2);await f.endpoint();await waitFor(f,()=>f.calls.some(call=>call.action==='practice_cycle'));const cycle=f.calls.find(call=>call.action==='practice_cycle');assert.equal(cycle.sellerTurn.text,'First part of the seller turn. Second part completes the seller turn.','ordered reconstruction is based on packet sequence, not response order');assert.deepEqual(cycle.sellerTurn.sourceEvidenceIds,['0','1'],'each source packet remains separately attested');assert.equal(cycle.sellerTurn.integrity,'complete');}finally{await act(()=>f.tree.unmount());}
});

test('validated Alex response renders while adaptive navigation is still pending',async()=>{
 const playbookText='# Field Practice\n## Opening\nSet a clear purpose for this conversation.\n## Discovery\nAsk what outcome matters most to your team.',next='Ask what outcome matters most to your team.',f=await setup({synthetic:true,practiceTurnMode:'turn_based_v1',coachDelay:180,audioText:'A natural seller response to the approved opening.',scriptNavigationResponse:body=>({selectedSalesMode:'scripted',playbookLoaded:true,currentScriptSection:'opening',recommendedScriptSection:'discovery',previousScriptSection:'opening',previousScriptStepId:'opening-1',routeDirection:'advance',routeReason:'Validated ordinary progression.',buyerIntent:null,buyingSignalStrength:'none',activeObjectionOrConfusion:null,readinessToClose:'not_ready',approvedScriptBranchId:null,currentScriptStepId:'discovery-1',scriptStepId:'discovery-1',visibleScriptText:next,staySilent:false,currentScriptStepStatus:'not_started',currentScriptStepWasSpoken:false,currentScriptStepComplete:false,nextSequentialScriptStepId:null,adaptiveOverride:false,activeAdaptiveRoute:false,resumeScriptSection:null,resumeScriptStepId:null,sequence:body.sequence})});
 try{await act(()=>f.tree.root.findByType('select').props.onChange({target:{value:'scripted'}}));const file=f.tree.root.findAllByType('input').find(input=>input.props.type==='file');await act(async()=>file.props.onChange({currentTarget:{files:[{name:'field.md',size:playbookText.length,text:async()=>playbookText}]}}));await start(f);await f.activity();await f.chunk();await waitFor(f,()=>diagnostics(f).transcriptTranscribed===1);await f.endpoint();await waitFor(f,()=>f.calls.some(call=>call.action==='coach'&&call.practiceMode===true));const navigationCall=f.calls.find(call=>call.action==='coach'&&call.practiceMode===true);assert.equal(navigationCall.completedAt,undefined,'controlled navigation evaluation remains pending');const rendered=JSON.stringify(f.tree.toJSON());assert.match(rendered,/Alex \(synthetic buyer\)/,'validated buyer text is rendered before navigation returns');assert.match(rendered,/Alex finished — your microphone is resuming/,'UI state distinguishes buyer playback handover from pending navigation');assert.doesNotMatch(rendered,/Alex is preparing a response/,'the page-level notice does not remain frozen on the prior generation state');assert.doesNotMatch(rendered,new RegExp(next),'next wording is not exposed before application navigation commits');assert.ok(diagnostics(f).practiceTurns.some(turn=>turn.role==='buyer'&&turn.finalized),'only a validated buyer turn is rendered');await waitFor(f,()=>navigationCall.completedAt!==undefined);await waitFor(f,()=>JSON.stringify(f.tree.toJSON()).includes(next));const trace=f.tree.root.findAllByType('pre').map(node=>node.children.join('')).join('\n');assert.match(trace,/"latencyStage":"buyer_turn_finalized"/);assert.match(trace,/"latencyStage":"navigation_evaluation_started"/);assert.equal(f.calls.filter(call=>['approve','task','calendar','send'].includes(call.action)).length,0);}finally{await act(()=>f.tree.unmount());}
});

