 const playbookText='# Customer Rail\n## Opening\nOpen with a useful purpose.\n## Discovery\nExplore the customer outcome.',f=await setup({synthetic:true,practiceTurnMode:'turn_based_v1',audioDelay:80,audioText:body=>body.sequence===0?'First part of one seller turn.':'Second part after a brief pause.',practiceCycleResponse:body=>({sellerTurn:{...body.sellerTurn,serverAttestation:'a'.repeat(64)},buyerTurn:{id:'buyer-1',order:2,role:'buyer',text:'That is a useful topic for us.',startedAt:body.sellerTurn.endedAt,endedAt:body.sellerTurn.endedAt,finalized:true,boundary:'explicit',sourceEvidenceIds:['synthetic:buyer'],integrity:'complete',provenance:{sourceId:'root-practice-buyer',method:'practice_action',confidence:null}}})});
