function pressPracticeSpace(f,target={tagName:'BODY',closest:()=>null},patch={}){const listener=f.documentEvents.get('keydown');if(typeof listener!=='function')return false;let prevented=false;act(()=>listener({code:'Space',repeat:false,shiftKey:false,altKey:false,ctrlKey:false,metaKey:false,isComposing:false,keyCode:32,defaultPrevented:false,target,...patch,preventDefault(){prevented=true;}}));return prevented;}

